// Minimal multi-provider chat client using built-in fetch (Node 18+).
import { PROVIDER_DEFAULTS } from "./config.js";

export function resolveProvider(config) {
  let provider = config.provider;
  if (!provider) {
    if (process.env.OPENAI_API_KEY) provider = "openai";
    else if (process.env.ANTHROPIC_API_KEY) provider = "anthropic";
    else throw new Error("No provider set and no OPENAI_API_KEY / ANTHROPIC_API_KEY found.");
  }
  const defaults = PROVIDER_DEFAULTS[provider];
  if (!defaults) throw new Error(`Unknown provider: ${provider}`);
  const apiKey = process.env[defaults.keyEnv];
  if (!apiKey) throw new Error(`Missing ${defaults.keyEnv} for provider ${provider}.`);
  const model = config.model || defaults.model;
  return { provider, model, apiKey, base: defaults.base };
}

export async function complete({ provider, model, apiKey, base }, messages, { temperature }) {
  if (provider === "openai") {
    const res = await fetch(base, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${apiKey}` },
      body: JSON.stringify({ model, messages, temperature }),
    });
    if (!res.ok) throw new Error(`OpenAI ${res.status}: ${await res.text()}`);
    const data = await res.json();
    return data.choices?.[0]?.message?.content ?? "";
  }
  if (provider === "anthropic") {
    const system = messages.find((m) => m.role === "system")?.content;
    const rest = messages.filter((m) => m.role !== "system");
    const res = await fetch(base, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": apiKey,
        "anthropic-version": "2023-06-01",
      },
      body: JSON.stringify({ model, system, messages: rest, max_tokens: 1024, temperature }),
    });
    if (!res.ok) throw new Error(`Anthropic ${res.status}: ${await res.text()}`);
    const data = await res.json();
    return data.content?.map((b) => b.text).join("") ?? "";
  }
  throw new Error(`Unsupported provider: ${provider}`);
}

