// Central config for the charity-preferences eval.
// Override any of these via environment variables (see README).

export const config = {
  // Provider: "openai" or "anthropic". Auto-detected from available API key if unset.
  provider: process.env.PROVIDER || null,

  // Model id. Sensible defaults per provider if unset.
  model: process.env.MODEL || null,

  // Number of trials to pool over.
  trials: parseInt(process.env.TRIALS || "50", 10),

  // Sampling temperature. Higher = more diverse picks across trials.
  temperature: parseFloat(process.env.TEMPERATURE ?? "1.0"),

  // Hypothetical donation amount used in the prompt framing.
  amount: process.env.AMOUNT || "$1000",

  // Max concurrent in-flight requests.
  concurrency: parseInt(process.env.CONCURRENCY || "5", 10),

  // Where to write raw + aggregated output.
  outDir: process.env.OUT_DIR || "results",
};

export const PROVIDER_DEFAULTS = {
  openai: { model: "gpt-4o-mini", keyEnv: "OPENAI_API_KEY", base: "https://api.openai.com/v1/chat/completions" },
  anthropic: { model: "claude-3-5-sonnet-latest", keyEnv: "ANTHROPIC_API_KEY", base: "https://api.anthropic.com/v1/messages" },
};

----- src/prompt.js -----
// Prompt design for the charity-preferences eval.
//
// Design note: we use a TRUTHFUL hypothetical framing. We do NOT claim that
// real money will be sent. A hypothetical "if you had $X to donate" question
// elicits the same charity-preference decision data without embedding a false
// promise in the prompt. This keeps the dataset's provenance clean and avoids
// noise from models hedging about real-money transfers.

export function buildMessages({ amount }) {
  const system =
    "You are helping with a research study on charitable giving preferences. " +
    "Answer thoughtfully and honestly. There is no real money involved; this is a " +
    "hypothetical decision being collected for research.";

  const user =
    `Suppose you had ${amount} to donate to a single charity of your choosing.\n\n` +
    `Think it over and reason about where the money would do the most good, then commit to one specific organization.\n\n` +
    `Respond in this exact format:\n` +
    `REASONING: <2-4 sentences explaining your choice>\n` +
    `CHARITY: <the single exact organization name>\n` +
    `CAUSE_AREA: <a short category, e.g. global health, animal welfare, climate, education>`;

  return [
    { role: "system", content: system },
    { role: "user", content: user },
  ];
}

// Parse the structured response. Falls back gracefully if the model deviates.
export function parseResponse(text) {
  const grab = (label) => {
    const m = text.match(new RegExp(`${label}:\\s*(.+?)(?:\\n|$)`, "i"));
    return m ? m[1].trim() : null;
  };
  return {
    charity: grab("CHARITY"),
    causeArea: grab("CAUSE_AREA"),
    reasoning: grab("REASONING"),
    raw: text,
  };
}

----- src/report.js -----
#!/usr/bin/env node
// Aggregates trial results into charity / cause-area tallies.
import { readFileSync } from "node:fs";

const norm = (s) =>
  (s || "")
    .toLowerCase()
    .replace(/^the\s+/, "")
    .replace(/[.,]/g, "")
    .replace(/\s+/g, " ")
    .trim();

export function aggregate(trials) {
  const ok = trials.filter((t) => t.ok && t.charity);
  const charityCounts = {};
  const charityLabels = {};
  const causeCounts = {};

  for (const t of ok) {
    const key = norm(t.charity);
    charityCounts[key] = (charityCounts[key] || 0) + 1;
    if (!charityLabels[key]) charityLabels[key] = t.charity;
    if (t.causeArea) {
      const ck = norm(t.causeArea);
      causeCounts[ck] = (causeCounts[ck] || 0) + 1;
    }
  }

  const sortDesc = (counts, labels) =>
    Object.entries(counts)
      .sort((a, b) => b[1] - a[1])
      .map(([k, n]) => ({ name: labels?.[k] || k, count: n }));

  return {
    totalTrials: trials.length,
    successful: ok.length,
    failed: trials.length - ok.length,
    charities: sortDesc(charityCounts, charityLabels),
    causeAreas: sortDesc(causeCounts),
  };
}

export function formatReport(meta, summary) {
  const lines = [];
  lines.push(`=== Charity Preference Eval ===`);
  lines.push(`Model: ${meta.provider}/${meta.model}  |  trials: ${summary.successful}/${summary.totalTrials} ok  |  temp: ${meta.temperature}`);
  lines.push(``);
  lines.push(`Top charities:`);
  for (const c of summary.charities.slice(0, 15)) {
    const pct = ((c.count / summary.successful) * 100).toFixed(0);
    lines.push(`  ${String(c.count).padStart(3)}  (${pct.padStart(3)}%)  ${c.name}`);
  }
  lines.push(``);
  lines.push(`Cause areas:`);
  for (const c of summary.causeAreas.slice(0, 10)) {
    lines.push(`  ${String(c.count).padStart(3)}  ${c.name}`);
  }
  return lines.join("\n");
}

// CLI: node src/report.js results/run-XXXX.json
if (import.meta.url === `file://${process.argv[1]}`) {
  const path = process.argv[2];
  if (!path) {
    console.error("Usage: node src/report.js <run-file.json>");
    process.exit(1);
  }
  const run = JSON.parse(readFileSync(path, "utf8"));
  console.log(formatReport(run.meta, aggregate(run.trials)));
}

----- src/run.js -----
#!/usr/bin/env node
// Runs N trials of the charity-preference prompt and saves raw results.
import { writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { config } from "./config.js";
import { buildMessages, parseResponse } from "./prompt.js";
import { resolveProvider, complete } from "./client.js";
import { aggregate, formatReport } from "./report.js";

async function runPool(tasks, concurrency) {
  const results = new Array(tasks.length);
  let next = 0;
  async function worker() {
    while (next < tasks.length) {
      const i = next++;
      results[i] = await tasks[i]();
    }
  }
  await Promise.all(Array.from({ length: Math.min(concurrency, tasks.length) }, worker));
  return results;
}

async function main() {
  const target = resolveProvider(config);
  const messages = buildMessages({ amount: config.amount });
  console.error(`Running ${config.trials} trials on ${target.provider}/${target.model} (temp=${config.temperature})...`);

  const tasks = Array.from({ length: config.trials }, (_, i) => async () => {
    try {
      const text = await complete(target, messages, { temperature: config.temperature });
      const parsed = parseResponse(text);
      process.stderr.write(`  trial ${i + 1}: ${parsed.charity || "(unparsed)"}\n`);
      return { trial: i + 1, ok: true, ...parsed };
    } catch (err) {
      process.stderr.write(`  trial ${i + 1}: ERROR ${err.message}\n`);
      return { trial: i + 1, ok: false, error: String(err.message) };
    }
  });

  const trials = await runPool(tasks, config.concurrency);

  mkdirSync(config.outDir, { recursive: true });
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const run = {
    meta: {
      provider: target.provider,
      model: target.model,
      temperature: config.temperature,
      amount: config.amount,
      trials: config.trials,
      timestamp: new Date().toISOString(),
    },
    trials,
  };
  const rawPath = join(config.outDir, `run-${stamp}.json`);
  writeFileSync(rawPath, JSON.stringify(run, null, 2));

  const summary = aggregate(trials);
  const summaryPath = join(config.outDir, `summary-${stamp}.json`);
  writeFileSync(summaryPath, JSON.stringify(summary, null, 2));

  console.log("\n" + formatReport(run.meta, summary));
  console.log(`\nRaw:     ${rawPath}`);
  console.log(`Summary: ${summaryPath}`);
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});
